package com.campusconnect.service;
import com.campusconnect.dao.StudentDAO; import com.campusconnect.model.Student; import com.campusconnect.util.*; import java.util.*;
public class StudentService { private final StudentDAO dao=new StudentDAO(); public List<Student> all(String q){return dao.findAll(q);} public Student profile(int id){return dao.findByUserId(id);} public int count(){return dao.count();}
 public void save(Student s,boolean update){ValidationUtil.required(s.getStudentId(),"Student ID");ValidationUtil.required(s.getName(),"Name");ValidationUtil.email(s.getEmail());ValidationUtil.phone(s.getPhone());ValidationUtil.required(s.getDepartment(),"Department");ValidationUtil.semester(s.getSemester());ValidationUtil.required(s.getHostelRoom(),"Hostel/Room");if(!update){ValidationUtil.required(s.getPasswordHash(),"Password");s.setPasswordHash(PasswordUtil.hash(s.getPasswordHash()));dao.insert(s);}else dao.update(s);} public void delete(int id){dao.delete(id);} }
